const express = require('express');
const { EventStoreDBClient, START } = require('@eventstore/db-client');
const { requireFleetAuth } = require('../auth');
const { db } = require('../db');

const router = express.Router();
const client = EventStoreDBClient.connectionString(process.env.EVENTSTORE_URL);

router.get('/api/queries/telemetry/:vin', requireFleetAuth, async (req, res) => {
  const { vin } = req.params;

  const vehicle = await db.query(
    'SELECT id FROM fleet_vehicles WHERE vin = $1 AND fleet_id = $2',
    [vin, req.fleet.id]
  );
  if (!vehicle.rows.length) {
    return res.status(403).json({ error: 'Access denied: vehicle not registered to your fleet' });
  }

  const pings = [];
  const stream = client.readStream(`vehicle-${vin}-telemetry`, { fromRevision: START, maxCount: 50 });
  for await (const resolved of stream) {
    pings.push(resolved.event.data);
  }

  res.json({ vin, telemetryRecords: pings });
});
